import{_ as t,o as i,c as s,a5 as a}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"Cycle de vie, propriété et nettoyage","description":"","frontmatter":{"title":"Cycle de vie, propriété et nettoyage","docId":"developer.lifecycle","translationKey":"developer.lifecycle","locale":"fr","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"3e866271067cf2c4d374aaccd9a6cdf6babf981df4deeff5313947cbf39b5cc7","translationRevision":"511aa954d0baa5c5931e7eb3824fecb2fb7a9f1dd11106dd335ba9d01d93102a","order":50},"headers":[],"relativePath":"fr/developer/lifecycle.md","filePath":"fr/developer/lifecycle.md","lastUpdated":1794611623000}'),n={name:"fr/developer/lifecycle.md"};function r(l,e,o,d,p,c){return i(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="lifecycle-ownership-and-cleanup" tabindex="-1">Cycle de vie, propriété et nettoyage <a class="header-anchor" href="#lifecycle-ownership-and-cleanup" aria-label="Permalink to &quot;Cycle de vie, propriété et nettoyage {#lifecycle-ownership-and-cleanup}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Faire libérer au montage, à la reconnexion et à l’arrêt les ressources qu’ils possèdent. Comprenez l’<a href="./architecture.html">architecture</a> et utilisez un <code>TIKTOOLS_HOME</code> isolé pour les expériences natives de cycle de vie. Un désabonnement de l’interface et l’arrêt d’un hôte résolvent des problèmes de propriété différents.</p><h2 id="follow-the-desktop-lifetime" tabindex="-1">Suivre la durée de vie du bureau <a class="header-anchor" href="#follow-the-desktop-lifetime" aria-label="Permalink to &quot;Suivre la durée de vie du bureau {#follow-the-desktop-lifetime}&quot;">​</a></h2><p><code>crates/tiktools-desktop/src/app.rs</code> implémente le gestionnaire d’application Winit. La création de fenêtre et de WebView se fait sur le thread de la boucle d’événements. La fenêtre commence masquée et apparaît après l’envoi de <code>frontend-ready</code> par Vue. La fermeture masque la fenêtre lorsqu’une icône de notification existe ; sinon elle déclenche l’arrêt. Quit demande au cœur d’arrêter ses services avant la sortie de la boucle d’événements.</p><p><code>crates/tiktools-core/src/shutdown.rs</code> ferme rapidement l’admission au démarrage des plugins, arrête la coordination et la surveillance en arrière-plan, déconnecte le LIVE et vide le travail possédé. Les appels d’arrêt répétés attendent la même fin. Abandonner une future ne peut ni arrêter du code natif arbitraire ni annuler un effet externe.</p><h2 id="own-frontend-resources-explicitly" tabindex="-1">Posséder explicitement les ressources de l’interface <a class="header-anchor" href="#own-frontend-resources-explicitly" aria-label="Permalink to &quot;Posséder explicitement les ressources de l’interface {#own-frontend-resources-explicitly}&quot;">​</a></h2><p>Utilisez le modèle déjà suivi par <code>use-app-runtime.ts</code> :</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { onUnmounted } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;vue&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { useControlClient } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@/shared/api/use-control-client.ts&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> useControlClient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> stop</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> control.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">onTopic</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;points.changed&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // Actualiser ici la présentation validée du store propriétaire.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">onUnmounted</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(stop);</span></span></code></pre></div><p>Le corps du rappel appartient à l’entité propriétaire de la vue. Une fonctionnalité doit libérer ses abonnements, temporisateurs, trames d’animation et portées de requête, tandis que l’initialisation de l’application possède le rattachement et détachement du transport partagé. Un changement de modèle de widget doit libérer le contrôleur précédent plutôt que de laisser tourner ses temporisateurs d’alerte.</p><h2 id="expected-result-and-verification" tabindex="-1">Résultat attendu et vérification <a class="header-anchor" href="#expected-result-and-verification" aria-label="Permalink to &quot;Résultat attendu et vérification {#expected-result-and-verification}&quot;">​</a></h2><p>Quitter une page et y revenir ne multiplie pas les rappels. Une présentation masquée arrête les rendus inutiles sans suspendre la comptabilisation faisant autorité. La reconnexion signale les lacunes et recharge les instantanés ; elle ne rejoue pas les effets métier. Exécutez <code>bun scripts/task.ts test web cloud-lifecycle</code> et <code>bun scripts/task.ts test web request-scope</code> pour des exemples ciblés.</p><h2 id="recovery-and-limits" tabindex="-1">Récupération et limites <a class="header-anchor" href="#recovery-and-limits" aria-label="Permalink to &quot;Récupération et limites {#recovery-and-limits}&quot;">​</a></h2><p>Un démarrage QuickJS dépassant le délai peut rester incertain ; le gestionnaire conserve l’identité de son worker et bloque son remplacement au lieu de prétendre que l’arrêt a réussi. Certains parcours de contrôle synchrones du cycle de vie des plugins peuvent encore bloquer leur appelant. Traitez-les comme des limites d’implémentation, surtout lors du transfert à l’outil de mise à jour. Arrêtez proprement l’hôte propriétaire plutôt que de supprimer son verrou actif. La <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/shutdown.rs" target="_blank" rel="noreferrer">source de l’arrêt</a> et les tests d’exécution sont des preuves plus solides qu’un schéma historique de cycle de vie.</p><h2 id="operational-details" tabindex="-1">Détails de fonctionnement <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Détails de fonctionnement {#operational-details}&quot;">​</a></h2><p>L’arrêt ferme l’admission LIVE et draine l’entrée, puis annule les observateurs/déconnecte et arrête le polling des plugins. Il vide Analytics, résout les écritures de points (30 s), effectue le checkpoint SQLite (5 s) et termine l’arrêt natif. Timeout de polling, échec analytique, points non résolus ou échec de checkpoint rendent la mise à jour non sûre. <code>AppCore::update_shutdown_safe()</code> exige fin de l’arrêt et indicateur sûr ; la fin seule ne suffit pas. L’updater consomme ce résultat natif, sans bouton capable de certifier du travail incertain. Conservez journaux/récupération et résolvez l’incertitude avant remplacement.</p>`,16)])])}const k=t(n,[["render",r]]);export{h as __pageData,k as default};
